def transform_match(g, marker):
 R,C=len(g),len(g[0]); pts=[(r,c) for r in range(R) for c in range(C) if g[r][c]==marker]
 minr=min(r for r,c in pts);maxr=max(r for r,c in pts);minc=min(c for r,c in pts);maxc=max(c for r,c in pts)
 sh={(r-minr,c-minc) for r,c in pts}
 out=[row[:] for row in g]
 for dr in range(R-(maxr-minr+1)+1):
  for dc in range(C-(maxc-minc+1)+1):
   if all(g[dr+r][dc+c]==0 for r,c in sh):
    for r,c in sh:out[dr+r][dc+c]=marker
 return out
